import pandas as pd
from collections import Counter


def task_func(df):
    """Generate sales report excluding duplicate customers."""
    if not isinstance(df, pd.DataFrame):
        raise ValueError
    df_unique = df.drop_duplicates(subset='Customer', keep='first')
    total_sales = int(df_unique['Sales'].sum())
    cat_counts = Counter(df_unique['Category'])
    if not cat_counts:
        most_popular = None
    else:
        max_count = max(cat_counts.values())
        most_popular = None
        for cat in df_unique['Category']:
            if cat_counts[cat] == max_count:
                most_popular = cat
                break
    return {'Total Sales': total_sales, 'Most Popular Category': most_popular}

