import numpy as np
from sklearn.decomposition import PCA
import matplotlib.pyplot as plt


def task_func(data, n_components=2, random_state=None):


    class PCAToolkit:

        def __init__(self, data, n_components, random_state):
            self.data = data
            self.n_components = n_components
            self.random_state = random_state

        def perform_pca(self):
            pca = PCA(n_components=self.n_components, random_state=self.
                random_state)
            return pca.fit_transform(self.data)


    class Visualizer:

        def __init__(self, transformed_data):
            self.transformed_data = transformed_data

        def plot_results(self):
            fig = plt.figure()
            ax = fig.add_subplot(111)
            if self.transformed_data.shape[1] == 1:
                y_values = np.zeros_like(self.transformed_data[:, 0])
                ax.scatter(self.transformed_data[:, 0], y_values)
            else:
                ax.scatter(self.transformed_data[:, 0], self.
                    transformed_data[:, 1])
            return ax
    toolkit = PCAToolkit(data, n_components, random_state)
    transformed_data = toolkit.perform_pca()
    visualizer = Visualizer(transformed_data)
    ax = visualizer.plot_results()
    return {'transformed_data': transformed_data, 'ax': ax}

import numpy as np
import pandas as pd
import logging
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.DEBUG)


def task_func(myList):
    if not isinstance(myList, list):
        logger.error('Input is not a list')
        raise TypeError('Input must be a list')
    if len(myList) == 0:
        logger.debug('Empty list provided')
        return np.array([])
    for idx, val in enumerate(myList):
        if not isinstance(val, (int, float, np.number)):
            logger.error(f'Non-numeric value at index {idx}: {val}')
            raise ValueError('All elements must be numeric')
    arr = np.array(myList, dtype=float)
    min_val = pd.Series(myList).min()
    max_val = pd.Series(myList).max()
    if min_val == max_val:
        logger.debug('All values are identical; returning zeros')
        return np.zeros_like(arr)
    normalized = (arr - min_val) / (max_val - min_val)
    min_val_dup = pd.Series(myList).min()
    max_val_dup = pd.Series(myList).max()
    if min_val_dup == max_val_dup:
        return np.zeros_like(arr)
    normalized_dup = (arr - min_val_dup) / (max_val_dup - min_val_dup)
    return normalized

import hashlib


def task_func(word: str) ->str:
    pairs = []
    i = 0
    while i < len(word) - 1:
        pairs.append(word[i:i + 2])
        i += 1
    counts = {}
    for p in pairs:
        if p in counts:
            counts[p] += 1
        else:
            counts[p] = 1
    rep = '{'
    first = True
    for k in counts:
        if not first:
            rep += ', '
        rep += f"'{k}': {counts[k]}"
        first = False
    rep += '}'
    return hashlib.md5(rep.encode()).hexdigest()

