import logging
logging.basicConfig(level=logging.INFO)


def task_func(x):
    """Return the subsequence (list of letters) with minimum total length."""
    if not isinstance(x, dict):
        raise TypeError('Input must be a dictionary')
    if not x:
        return []
    for key, value in x.items():
        if not isinstance(value, (int, float)):
            raise ValueError(f'Length for key {key} must be numeric')
    min_sum = None
    min_subseq = []

    def dfs(items, idx, current, total):
        nonlocal min_sum, min_subseq
        if idx == len(items):
            if current:
                if min_sum is None or total < min_sum:
                    min_sum = total
                    min_subseq = current.copy()
            return
        dfs(items, idx + 1, current + [items[idx][0]], total + items[idx][1])
        dfs(items, idx + 1, current, total)
    items = list(x.items())
    dfs(items, 0, [], 0)
    return min_subseq

