        return 'The distribution of values is uniform.', plt.gca()
    else:
        return 'The distribution of values is not uniform.', plt.gca()

import os
from pathlib import Path


def task_func(directory_path: str):
    dir_path = Path(directory_path)

    def _rename_and_return(fp: Path):
        words = tuple(fp.name.split('.'))
        new_name = '.'.join(reversed(words))
        fp.rename(fp.with_name(new_name))
        return new_name
    return [_rename_and_return(fp) for fp in dir_path.iterdir() if fp.is_file()
        ]

