import re
import os
import shutil


def task_func(source_dir, target_dir, *args):
    file_pattern = args[0] if args else '\\b[A-Za-z0-9]+\\.(txt|doc|docx)\\b'
    if not os.path.exists(target_dir):
        os.makedirs(target_dir)
    matched = set(f for f in os.listdir(source_dir) if re.search(
        file_pattern, f))
    for f in matched:
        shutil.move(os.path.join(source_dir, f), os.path.join(target_dir, f))
    return len(matched)

from random import Random
import time
from itertools import cycle


def task_func(n_colors, colors=['Red', 'Green', 'Blue', 'Yellow', 'Purple'],
    rng_seed=None):
    if n_colors <= 0:
        return []
    if not isinstance(colors, list) or len(colors) == 0:
        raise ValueError('Colors must be a non-empty list of strings')
    random_gen = Random()
    if rng_seed is not None:
        random_gen.seed(rng_seed)
    else:
        random_gen.seed(time.time())
    color_cycle = cycle(colors * (n_colors // len(colors) + 2))
    pattern = []
    for i in range(n_colors):
        if i % 2 == 0:
            try:
                cycle_color = next(color_cycle)
                pattern.append(cycle_color)
            except StopIteration:
                pattern.append(random_gen.choice(colors))
        else:
            pattern.append(random_gen.choice(colors))
    return pattern

