import os
from collections import defaultdict
INVALID_CHARACTERS = set('!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~ \t\n\r\x0b\x0c')


def task_func(directory_path):
    if not os.path.exists(directory_path):
        raise FileNotFoundError(f"Directory '{directory_path}' not found")
    summary = defaultdict(int)
    invalid_dir = os.path.join(directory_path, 'Invalid')
    for filename in os.listdir(directory_path):
        file_path = os.path.join(directory_path, filename)
        if os.path.isdir(file_path):
            continue
        is_invalid = any(c in INVALID_CHARACTERS for c in filename)
        if is_invalid:
            os.makedirs(invalid_dir, exist_ok=True)
            shutil.move(file_path, invalid_dir)
            summary['Invalid'] += 1
        else:
            ext = os.path.splitext(filename)[1][1:].lower()
            if ext:
                new_dir = os.path.join(directory_path, ext)
                os.makedirs(new_dir, exist_ok=True)
                shutil.move(file_path, new_dir)
                summary[ext] += 1
    return dict(summary)

