import numpy as np
from matplotlib import pyplot as plt


def task_func(P, T):
    if not (isinstance(P, np.ndarray) and isinstance(T, np.ndarray)):
        raise TypeError('Inputs must be NumPy arrays')
    if P.ndim != 2 or T.ndim != 3:
        raise ValueError('Invalid input dimensions')
    if P.shape[1] != T.shape[0]:
        raise ValueError('Matrix multiplication not possible')
    product = np.zeros((P.shape[0], T.shape[1], T.shape[2]))
    for i in range(P.shape[0]):
        for j in range(T.shape[1]):
            for k in range(T.shape[2]):
                product[i, j, k] = np.dot(P[i, :], T[:, j, k])
    fig, ax = plt.subplots(figsize=(10, 8))
    heatmap = ax.imshow(product[:, :, 0], cmap='viridis', origin='lower')
    plt.colorbar(heatmap)
    plt.title('Heatmap Visualization of Matrix Product')
    plt.xlabel('X-axis')
    plt.ylabel('Y-axis')
    return product, ax

import os, shutil, hashlib


def task_func(ROOT_DIR, DEST_DIR, SPECIFIC_HASH):
    moved = 0
    if not os.path.isdir(DEST_DIR):
        os.makedirs(DEST_DIR, exist_ok=True)
    all_files = [os.path.join(dp, f) for dp, dn, filenames in os.walk(
        ROOT_DIR) for f in filenames]
    for fpath in all_files:
        try:
            with open(fpath, 'rb') as fp:
                data = fp.read()
                h = hashlib.md5(data).hexdigest()
        except Exception:
            continue
        if h == SPECIFIC_HASH:
            try:
                with open(fpath, 'rb') as fp2:
                    data2 = fp2.read()
                    h2 = hashlib.md5(data2).hexdigest()
                if h2 == SPECIFIC_HASH:
                    shutil.move(fpath, DEST_DIR)
                    moved += 1
            except Exception:
                pass
    return moved

import random
POSSIBLE_LETTERS = ['a', 'b', 'c']


def task_func(word):
    if not all(c.isalpha() for c in word):
        raise ValueError('Invalid input')
    pairs = []
    n = len(word)
    if n >= 2:
        for i in range(n - 1):
            pairs.append(word[i] + word[i + 1])
    result = []
    for _ in range(len(POSSIBLE_LETTERS)):
        if not pairs:
            result.append('')
        else:
            result.append(random.choice(pairs))
    return result

import xmltodict
import json


def task_func(s, file_path):
    """Converts an XML string to a dictionary and saves it as JSON."""

    def parse_xml(xml_str):
        return xmltodict.parse(xml_str)

    def save_to_json(dct, path):
        with open(path, 'w') as f:
            json.dump(dct, f, indent=4)
    data_dict = parse_xml(s)
    save_to_json(data_dict, file_path)
    return data_dict

