import numpy as np
from collections import Counter
import scipy.fft


def task_func(data, repetitions):
    if not data or repetitions <= 0:
        return {'mode': np.array([], dtype='object'), 'count': np.array([],
            dtype=int), 'fft': np.array([])}
    repeated_data = [item for item in data for _ in range(repetitions)]
    counts = Counter(repeated_data)
    max_count = max(counts.values())
    mode_items = [value for value, count in counts.items() if count ==
        max_count]
    fft_result = scipy.fft.fft(data)
    return {'mode': np.sort(np.array(mode_items)), 'count': np.array([
        max_count] * len(mode_items)), 'fft': fft_result}

