def task_func(T1: Tuple[Tuple[str]], max_value: int=100) ->Tuple[int]:

    def generate_random(n: int, max_val: int) ->List[int]:
        return [random.randint(0, max_val - 1) for _ in range(n)]

    def calculate_percentiles(numbers: List[int]) ->Tuple[int, int, int]:
        q = quantiles(numbers)
        return int(q[0]), int(q[1]), int(q[2])
    try:
        flattened = [int(num) for sublist in T1 for num in sublist]
        total = sum(flattened)
        random_numbers = generate_random(total, max_value)
        p25, p50, p75 = calculate_percentiles(random_numbers)
        return p25, p50, p75
    except ValueError:
        raise ValueError('Invalid input: non-integer values found in T1')
    except TypeError:
        raise TypeError('Invalid input type for T1 or max_value')

