import json
from enum import Enum


class Color(Enum):
    RED = 1
    GREEN = 2
    BLUE = 3


def task_func(my_obj):
    """Serializes an object into a JSON string with support for complex data types like Enum."""

    def custom_encode(obj):
        if isinstance(obj, Enum):
            return obj.value
        return None

    def serializer(obj):
        if isinstance(obj, Enum):
            return obj.name
        try:
            return json.dumps(obj)
        except TypeError:
            return str(obj)
    return json.dumps(my_obj, default=serializer, ensure_ascii=False,
        indent=None)

