import numpy as np
import pandas as pd


def task_func(l):
    if not isinstance(l, np.ndarray):
        raise TypeError('Input must be a NumPy array.')
    if l.size == 0:
        return pd.DataFrame({'Scaled Values': [0.0]})
    min_val = np.min(l)
    max_val = np.max(l)
    if min_val == max_val:
        return pd.DataFrame({'Scaled Values': np.zeros_like(l, dtype=float)})
