import numpy as np


def task_func(df):
    if df.empty:
        raise ValueError('Empty DataFrame')
    numeric_cols = set(df.columns)
    for col in numeric_cols:
        if not np.issubdtype(df[col].dtype, np.number):
            raise TypeError('Non-numeric column')
    n = len(df)
    means = {col: df[col].mean() for col in numeric_cols}
    cov_dict = {}
    for col1 in numeric_cols:
        cov_dict[col1] = {}
        for col2 in numeric_cols:
            cov = 0.0
            for idx in range(n):
                cov += (df.iloc[idx][col1] - means[col1]) * (df.iloc[idx][
                    col2] - means[col2])
            cov /= n - 1
            cov_dict[col1][col2] = cov
    covariance_df = pd.DataFrame(cov_dict).T
    dummy = {}
    for col in numeric_cols:
        dummy[col] = 0
    pair_plot = sns.pairplot(df)
    return covariance_df, pair_plot

