import statistics
from collections import Counter


def task_func(elements, subset_size):
    """Return mean, median, and mode of sums of all subsets of given size."""

    def gen_subsets(idx, current):
        if len(current) == subset_size:
            yield tuple(current)
            return
        if idx == len(elements):
            return
        yield from gen_subsets(idx + 1, current + [elements[idx]])
        yield from gen_subsets(idx + 1, current)
    sums = [sum(sub) for sub in gen_subsets(0, [])]
    mode_val = Counter(sums).most_common(1)[0][0]
    return {'mean': statistics.mean(sums), 'median': statistics.median(sums
        ), 'mode': mode_val}

