        age_seconds = get_file_age(file_path)
        return age_seconds >= days_limit * 86400

    def has_valid_extension(file_name: str, extensions: List[str]) ->bool:
        file_ext = os.path.splitext(file_name)[1]
        return file_ext.lower() in [ext.lower() for ext in extensions]
    target_extensions = ['.txt', '.csv', '.xlsx', '.docx', '.pdf']
    files_to_archive = []
    try:
        all_files = os.listdir(my_path)
        for file in all_files:
            file_path = os.path.join(my_path, file)
            if os.path.isfile(file_path):
                if has_valid_extension(file, target_extensions
                    ) and is_old_file(file_path, days_old):
                    files_to_archive.append(file_path)
        for old_file in files_to_archive:
            new_path = os.path.join(archive_dir, os.path.basename(old_file))
            os.replace(old_file, new_path)
    except Exception as e:
        raise RuntimeError(f'Error archiving files: {str(e)}')
    return archive_dir

