import json
from typing import Dict, Any
from hashlib import sha256
from os.path import join, isfile
from os import walk


def task_func(directory: str) ->str:
    """Generates SHA256 hashes for all files in the specified directory and its subdirectories,
    storing the results in a JSON file named 'hashes.json' within the given directory."""
    hash_dict: Dict[str, str] = {}
    for root, _, files in walk(directory):
        for file_name in files:
            file_path = join(root, file_name)
            if not isfile(file_path):
                continue
            try:
                with open(file_path, 'rb') as f:
                    file_content = f.read()
                    file_hash = sha256(file_content).hexdigest()
                    hash_dict[file_path] = file_hash
            except Exception as e:
                pass
    json_file = join(directory, 'hashes.json')
    try:
        with open(json_file, 'w') as f:
            json.dump(hash_dict, f)
    except Exception as e:
        raise RuntimeError(f'Failed to save hashes to {json_file}: {str(e)}')
    return json_file

import re
import urllib.parse
import ssl
import socket


def task_func(myString):
    """Extract HTTPS URLs, fetch SSL expiry dates, and return a dict of domains to expiry."""

    def _get_expiry(host, port):
        try:
            with socket.create_connection((host, port)) as sock:
                ctx = ssl.create_default_context()
                with ctx.wrap_socket(sock, server_hostname=host) as ssock:
                    cert = ssock.getpeercert()
                    return cert.get('notAfter')
        except ssl.SSLError:
            return None
    urls = re.findall('https://[^\\s,]+', myString)
    result = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        netloc = parsed.netloc
        if ':' in netloc:
            host, port_str = netloc.split(':', 1)
            try:
                port = int(port_str)
            except ValueError:
                port = 443
        else:
            host = netloc
            port = 443
        expiry = _get_expiry(host, port)
        if expiry:
            result[netloc] = expiry
    return result

