import pandas as pd
import numpy as np


def task_func(data, columns=None, fill_missing=None, num_range=None, seed=None
    ):
    if columns is None:
        columns = ['Name', 'Age', 'Occupation']
    if fill_missing is None:
        fill_missing = False
    if num_range is None:
        num_range = 0, 100
    if seed is not None:
        np.random.seed(seed)
    rows = []
    for tup in data:
        row = list(tup) + [None] * (len(columns) - len(tup))
        rows.append(row[:len(columns)])
    df = pd.DataFrame(rows, columns=columns)
    if fill_missing:
        for col in df.columns:
            non_none = df[col].dropna()
            if non_none.empty:
                continue
            if all(isinstance(v, (int, float)) for v in non_none):
                mask = df[col].isna()
                if mask.any():
                    rng_min, rng_max = num_range
                    random_vals = np.random.randint(rng_min, rng_max + 1,
                        size=mask.sum())
                    df.loc[mask, col] = random_vals
    return df

import secrets
import hashlib
from base64 import b64encode


def task_func(num, from_base, to_base, alphabet):

    def convert_base(number, src, dst):
        try:
            return int(number, src)
        except ValueError:
            raise ValueError(f'Invalid number format for base {src}')

    def hash_and_encode(value, salt):
        hashed = hashlib.sha256(bytes(value, 'utf-8') + bytes(salt, 'utf-8')
            ).digest()
        encoded = b64encode(hashed).decode()
        return encoded
    if from_base < 2:
        raise ValueError(
            f'Invalid base conversion: from_base {from_base} is less than 2')
    if to_base < 2:
        raise ValueError(
            f'Invalid base conversion: to_base {to_base} is less than 2')
    try:
        number = convert_base(num, from_base, to_base)
        salt = secrets.token_hex(16)
        encoded_value = hash_and_encode(str(number), salt)
        return encoded_value, salt
    except ValueError as e:
        raise ValueError(f'Invalid base conversion: {e}')

import os
