import matplotlib.pyplot as plt


def task_func(data):
    if not data:
        return None
    students = set()
    for d in data:
        students.update(d.keys())
    students = sorted(students)
    averages = {}
    for student in students:
        total = 0
        count = 0
        for d in data:
            if student in d:
                score = d[student]
                if score is None:
                    continue
                if not isinstance(score, (int, float)) or score < 0:
                    raise ValueError('Invalid score value')
                total += score
                count += 1
        if count == 0:
            averages[student] = 0
        else:
            averages[student] = total / count
    fig, ax = plt.subplots()
    bars = ax.bar(students, [averages[s] for s in students])
    ax.set_xlabel('Student')
    ax.set_ylabel('Average Score')
    ax.set_title('Average Student Scores')
    return ax

