import pandas as pd
from sklearn.decomposition import PCA


def task_func(array, seed=None):
    if array.ndim != 2:
        raise ValueError('Input must be a 2D array.')
    if array.size == 0:
        return pd.DataFrame(columns=['PC1', 'PC2'])
    n_components = min(2, array.shape[1])
    pca = PCA(n_components=n_components, random_state=seed)
    principal_components = pca.fit_transform(array)
    columns = ['PC1', 'PC2'][:n_components]
    return pd.DataFrame(principal_components, columns=columns)

