import pandas as pd
from typing import Dict, List


def task_func(data_dir: str, csv_file: str) ->pd.DataFrame:
    """
    Load a CSV file into a pandas DataFrame and replace the NaN values in numeric columns with the mean of the corresponding column.

    Args:
        data_dir (str): The path to the directory containing the CSV file.
        csv_file (str): The name of the CSV file to be processed.

    Returns:
        pd.DataFrame: A pandas DataFrame with the processed data.
    """

    def load_csv(file_path: str) ->pd.DataFrame:
        try:
            return pd.read_csv(file_path)
        except pd.errors.EmptyDataError:
            return pd.DataFrame()

    def process_numeric_columns(df: pd.DataFrame) ->pd.DataFrame:
        for column in df.columns:
            if pd.api.types.is_numeric_dtype(df[column]):
                mean = df[column].mean()
                df[column] = df[column].fillna(mean)
        return df
    file_path = os.path.join(data_dir, csv_file)
    df = load_csv(file_path)
    processed_df = process_numeric_columns(df)
    return processed_df

