import tempfile


def task_func(data_dict, source_directory, backup_directory):

    def add_key_to_dict(input_dict):
        input_dict['a'] = 1
        return input_dict

    def count_value_frequencies(input_dict):
        value_counts = {}
        for key in input_dict:
            if input_dict[key] not in value_counts:
                value_counts[input_dict[key]] = 1
            else:
                value_counts[input_dict[key]] += 1
        return dict(value_counts)

    def sort_dict_by_frequency(input_dict):
        sorted_items = sorted(input_dict.items(), key=lambda x: x[1],
            reverse=True)
        return sorted_items

    def backup_files(source_dir, backup_dir):
        try:
            with tempfile.TemporaryDirectory() as tmp_dir:
                for file in os.listdir(source_dir):
                    shutil.copy2(os.path.join(source_dir, file), tmp_dir)
                for file in os.listdir(tmp_dir):
                    shutil.move(os.path.join(tmp_dir, file), backup_dir)
            return True
        except Exception as e:
            print(f'Error backing up files: {e}')
            return False
    data_dict = add_key_to_dict(data_dict)
    value_frequencies = count_value_frequencies(data_dict)
    sorted_items = sort_dict_by_frequency(value_frequencies)
    backup_status = backup_files(source_directory, backup_directory)
    return data_dict, sorted_items, backup_status

import os
import shutil


def task_func(src_folder: str, backup_dir: str) ->bool:
    if not os.path.isdir(src_folder):
        raise ValueError('Source folder does not exist')
    if src_folder == backup_dir:
        return True
    if not os.path.isdir(backup_dir):
        os.makedirs(backup_dir, exist_ok=True)
    backup_path = os.path.join(backup_dir, os.path.basename(src_folder))
    if os.path.exists(backup_path):
        raise FileExistsError('Backup folder already exists')
    shutil.copytree(src_folder, backup_path)
    shutil.rmtree(src_folder)
    return True

import pandas as pd
import numpy as np
from sklearn.metrics import r2_score
ROWS = 100
COLUMNS = ['X', 'Y']


def task_func(df):
    if not isinstance(df, pd.DataFrame):
        raise TypeError('Input must be a pandas DataFrame')
    for col in COLUMNS:
        if col not in df.columns:
            raise ValueError(f'DataFrame must contain column {col}')
    X = np.array(df['X']).reshape(-1, 1)
    y = np.array(df['Y'])
    slope, intercept = np.polyfit(X.ravel(), y, 1)


    class LinearModel:

        def __init__(self):
            self.coef_ = slope
            self.intercept_ = intercept

        def score(self, X, y):
            return r2_score(y, self.predict(X))

        def predict(self, X):
            return X * self.coef_ + self.intercept_
    model = LinearModel()
    return model

