import os
import shutil
BACKUP_DIR = '/tmp/backup'


def task_func(directory):

    def get_backup_directories():
        if not os.path.exists(BACKUP_DIR):
            return None
        backups = os.listdir(BACKUP_DIR)
        return backups

    def restore_from_backup(backup_dir):
        try:
            shutil.rmtree(directory)
            shutil.copytree(os.path.join(BACKUP_DIR, backup_dir), directory)
            return directory
        except Exception as e:
            raise Exception(str(e))
    backups = get_backup_directories()
    if not backups:
        if os.path.exists(BACKUP_DIR):
            return 'No backups found in /tmp/backup. Cannot rollback update.'
        else:
            return (
                f'Backup directory {BACKUP_DIR} does not exist. Cannot rollback update.'
                )
    try:
        restore_from_backup(backups[0])
        return directory
    except Exception as e:
        raise e

