import pandas as pd
import inspect


def task_func(f_list, file_path):
    if not isinstance(file_path, str):
        raise ValueError('file_path must be a string')
    if not isinstance(f_list, list) or len(f_list) == 0:
        raise ValueError('f_list must be a non-empty list')
    for f in f_list:
        if not callable(f):
            raise ValueError('All elements in f_list must be callable')
    data = []
    for f in f_list:
        name = f.__name__
        sig = inspect.signature(f)
        params = sig.parameters
        num_args = len(params)
        defaults = {k: v.default for k, v in params.items() if v.default is not
            inspect._empty}
        is_lambda = name == '<lambda>'
        data.append({'Function Name': name, 'Number of Arguments': num_args,
            'Defaults': str(defaults) if defaults else None, 'Is Lambda':
            is_lambda})
    df = pd.DataFrame(data)
    try:
        df.to_csv(file_path, index=False)
    except OSError as e:
        raise IOError(e)
    return None

