import os, re, glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    """Return absolute paths of files in directory matching extensions that contain pattern (case-insensitive)."""
    regex = re.compile(pattern, re.IGNORECASE)
    matched = set()
    for ext in extensions:
        for file_path in glob.glob(os.path.join(directory, ext)):
            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore'
                    ) as f:
                    content = f.read()
                if regex.search(content):
                    matched.add(os.path.abspath(file_path))
            except OSError:
                continue
    return list(matched)

