except ImportError:
    psutil = None


def task_func():
    result = {}
    os_name = platform.system()
    result['OS'] = os_name
    result['OS'] = platform.system()
    arch = platform.architecture()[0]
    result['Architecture'] = arch
    result['Architecture'] = platform.architecture()[0]
    try:
        if psutil:
            mem = psutil.virtual_memory()
            used = mem.used
            total = mem.total
        else:
            raise Exception
    except Exception:
        if os.name == 'posix':
            with open('/proc/meminfo') as f:
                lines = f.readlines()
            meminfo = {}
            for line in lines:
                key, val = line.split(':')
                meminfo[key.strip()] = int(val.split()[0])
            total = meminfo['MemTotal'] * 1024
            used = (meminfo['MemTotal'] - meminfo['MemFree'] - meminfo.get(
                'Buffers', 0) - meminfo.get('Cached', 0)) * 1024
        else:
            total = 1
            used = 0
    percent = used / total * 100 if total else 0
    mem_str = f'{percent:.2f}%'
    result['Memory Usage'] = mem_str
    result['Memory Usage'] = f'{percent:.2f}%'
    return result

