import numpy as np
from pandas import DataFrame
from matplotlib import pyplot as plt
from scipy.stats import kstest
from typing import Tuple


def task_func(data: np.ndarray) ->Tuple[DataFrame, plt.Axes, float | None]:
    if not isinstance(data, np.ndarray):
        raise TypeError('Input must be a numpy array.')
    if data.ndim != 2 or data.shape[1] != 8:
        raise ValueError('Data must be a 2D array with exactly eight columns.')

    def compute_averages(data_array: np.ndarray) ->np.ndarray:
        return np.mean(data_array, axis=1)
    averages = compute_averages(data)
    df = DataFrame(data)
    df['Average'] = averages

    def plot_distribution(averages_data: np.ndarray, ax: plt.Axes) ->None:
        ax.hist(averages_data, bins=20, density=True, alpha=0.6, color='blue')
        ax.plot(averages_data, np.zeros_like(averages_data), 'r+')
    fig, ax = plt.subplots(figsize=(10, 6))
    plot_distribution(averages, ax)

    def perform_normality_test(averages_data: np.ndarray) ->(float | None):
        if len(averages_data) >= 20:
            return kstest(averages_data, 'norm').pvalue
        else:
            return None
    p_value = perform_normality_test(averages)
    return df, ax, p_value

