from typing import List
import logging


def task_func(source_dir: str, dest_dir: str, extension: str) ->int:
    if not os.path.exists(source_dir):
        raise FileNotFoundError(f'Source directory {source_dir} does not exist'
            )
    if not os.path.isdir(dest_dir):
        raise NotADirectoryError(
            f'Destination {dest_dir} is not a valid directory')
    if not isinstance(extension, str) or len(extension.strip()) == 0:
        raise ValueError('Extension must be a non-empty string')
    moved_files: List[str] = []
    try:
        for filename in os.listdir(source_dir):
            if filename.endswith(f'.{extension}') and os.path.isfile(os.
                path.join(source_dir, filename)):
                file_path = os.path.join(source_dir, filename)
                shutil.move(file_path, dest_dir)
                moved_files.append(filename)
        return len(moved_files)
    except Exception as e:
        logging.error(f'Error occurred during file moving: {str(e)}')
        raise

import numpy as np
from sklearn.cluster import KMeans


def task_func(data, n_clusters=2, random_state=0):
    if not data:
        raise ValueError('Data cannot be empty')
    for point in data:
        if not isinstance(point[1], (int, float)) or not isinstance(point[2
            ], (int, float)):
            raise ValueError('Coordinates must be numeric')
    points = np.array([point[1:] for point in data])
    kmeans = KMeans(n_clusters=n_clusters, random_state=random_state)
    labels = kmeans.fit_predict(points)
    return labels

