import pandas as pd
import numpy as np


def task_func(df: pd.DataFrame, features: list) ->pd.DataFrame:

    def standard_scale(series):
        mean = series.mean()
        std = series.std(ddof=0)
        if std == 0:
            return series - mean
        return (series - mean) / std
    df_copy = df.copy()
    for feature in features:
        if feature in df_copy.columns:
            df_copy[feature] = standard_scale(df_copy[feature])
    return df_copy

