import pandas as pd
import numpy as np


def task_func(rows, columns=None, seed=None):
    if not isinstance(rows, int):
        raise ValueError
    if rows <= 0:
        raise ValueError
    if columns is None:
        columns = ['A', 'B', 'C', 'D', 'E', 'F']
    if seed is None:
        seed = 42
    rng = np.random.default_rng(seed)
    data = rng.integers(1, 101, size=(rows, len(columns)))
    df = pd.DataFrame(data, columns=columns)
    stats = {}
    for col in columns:
        col_data = df[col].tolist()
        mean_val = sum(col_data) / len(col_data)
        sorted_data = sorted(col_data)
        mid = len(sorted_data) // 2
        if len(sorted_data) % 2 == 0:
            median_val = (sorted_data[mid - 1] + sorted_data[mid]) / 2
        else:
            median_val = sorted_data[mid]
        stats[col] = {'mean': mean_val, 'median': median_val}
    return df, stats

