import os
from pathlib import Path
import tarfile


def task_func(directory, backup_dir):
    if not Path(directory).exists():
        raise FileNotFoundError(f'Source directory {directory} does not exist')
    log_files = list(Path(directory).glob('*.log'))
    if not log_files:
        return 'No logs found to backup'
    backup_path = Path(backup_dir) / 'logs_backup.tar.gz'
    with tarfile.open(backup_path, 'w:gz') as tar:
        for file in log_files:
            tar.add(file)
    for file in log_files:
        os.remove(file)
    return str(backup_path)

import pandas as pd
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt


def task_func(df, n_clusters=3, random_state=0):
    if df.empty:
        raise ValueError('Input DataFrame is empty')
    required_columns = ['group', 'date', 'value']
    if not all(col in df.columns for col in required_columns):
        raise ValueError('Missing one or more required columns: {}'.format(
            required_columns))
    try:
        df['date'] = pd.to_datetime(df['date'])
    except ValueError:
        raise ValueError("Invalid date format in column 'date'")
    df['date_ord'] = df['date'].apply(lambda x: x.toordinal())
    kmeans = KMeans(n_clusters=n_clusters, random_state=random_state)
    clusters = kmeans.fit_predict(df[['date_ord', 'value']])
    plt.scatter(df['date_ord'], df['value'], c=clusters)
    plt.xlabel('Date (ordinal)')
    plt.ylabel('Value')
    plt.title('KMeans Clustering of Value vs Date')
    return plt.gca()


class TaskFuncAlternative:

    def __init__(self, df, n_clusters=3, random_state=0):
        self.df = df
        self.n_clusters = n_clusters
        self.random_state = random_state

    def _check_input(self):
        if self.df.empty:
            raise ValueError('Input DataFrame is empty')
        required_columns = ['group', 'date', 'value']
        if not all(col in self.df.columns for col in required_columns):
            raise ValueError('Missing one or more required columns: {}'.
                format(required_columns))
        try:
            self.df['date'] = pd.to_datetime(self.df['date'])
        except ValueError:
            raise ValueError("Invalid date format in column 'date'")

    def _perform_clustering(self):
        self.df['date_ord'] = self.df['date'].apply(lambda x: x.toordinal())
        kmeans = KMeans(n_clusters=self.n_clusters, random_state=self.
            random_state)
        clusters = kmeans.fit_predict(self.df[['date_ord', 'value']])
        return clusters

    def _plot_clusters(self, clusters):
        plt.scatter(self.df['date_ord'], self.df['value'], c=clusters)
        plt.xlabel('Date (ordinal)')
        plt.ylabel('Value')
        plt.title('KMeans Clustering of Value vs Date')
        return plt.gca()

    def task_func(self):
        self._check_input()
        clusters = self._perform_clustering()
        return self._plot_clusters(clusters)


