import logging
logging.basicConfig(level=logging.DEBUG)


def task_func(data_dict):
    if not isinstance(data_dict, dict):
        logging.error('Input is not a dictionary')
        raise TypeError('Input must be a dictionary')
    for k, v in data_dict.items():
        if not isinstance(v, (int, float)):
            logging.error(f'Value for key {k} is not numeric')
            raise ValueError(
                f'All values must be numeric, got {type(v)} for key {k}')
    if len(data_dict) <= 1:
        message = 'The distribution is uniform.'
        return None, message
    counts1 = list(data_dict.values())
    counts2 = []
    for val in data_dict.values():
        counts2.append(val)
    uniform = True
    first = counts1[0]
    for c in counts1:
        if c != first:
            uniform = False
            break
    if uniform:
        for c in counts2:
            if c != first:
                uniform = False
                break
    message = ('The distribution is uniform.' if uniform else
        'The distribution is not uniform.')
    return None, message

import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):

    def preprocess_locations(d):
        processed = []
        for loc, val in d.items():
            if isinstance(val, dict) and 'Lat' in val and 'Lon' in val:
                processed.append({'Location': loc, 'Lat': val['Lat'], 'Lon':
                    val['Lon']})
            elif isinstance(val, str):
                geolocator = Photon(user_agent='geoapiExercises')
                geocoded = geolocator.geocode(val)
                processed.append({'Location': loc, 'Lat': geocoded.latitude,
                    'Lon': geocoded.longitude})
            else:
                raise ValueError('Invalid location format for {}'.format(loc))
        return pd.DataFrame(processed)

    def create_map(df):
        if df.empty:
            return folium.Map()
        center = [df.iloc[0]['Lat'], df.iloc[0]['Lon']]
        m = folium.Map(location=center, zoom_start=4)
        for _, row in df.iterrows():
            folium.Marker([row['Lat'], row['Lon']], popup=row['Location']
                ).add_to(m)
        return m
    locations_df = preprocess_locations(dic)
    return create_map(locations_df)

