import pandas as pd


def task_func(data, mapping):
    df = pd.DataFrame(data)
    for col in df.columns:
        for idx in df.index:
            val = df.at[idx, col]
            if isinstance(val, str):
                for acr, full in mapping.items():
                    if acr in val:
                        val = val.replace(acr, full)
                df.at[idx, col] = val
    return df

import string
PUNCTUATION_SET = set(string.punctuation)


def task_func(text):
    result = {'words': 0, 'punct': 0}
    for ch in text:
        if ch in PUNCTUATION_SET:
            result['punct'] += 1
    tokens = text.split()
    for token in tokens:
        cleaned = token.strip(''.join(PUNCTUATION_SET))
        if cleaned:
            result['words'] += 1
    duplicate_word_count = 0
    for token in tokens:
        if token:
            duplicate_word_count += 1
    return result['words'], result['punct']

import json
import pandas as pd


def task_func(file_path, key):
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
        df = pd.DataFrame(data)
        df = df.drop(columns=[key])
        with open(file_path, 'w') as f:
            json.dump(df.to_dict('records'), f)
        return df
