import pandas as pd


def task_func(my_tuple, path_csv_files):
    result = {column: {} for column in my_tuple}
    for file in path_csv_files:
        try:
            df = pd.read_csv(file)
            for column in my_tuple:
                if column in df.columns:
                    for value in df[column].unique():
                        result[column][value] = result[column].get(value, 0
                            ) + df[column].eq(value).sum()
        except Exception as e:
            raise e
    return result

