def task_func(articles, timezone):
    if not articles:
        raise ValueError('Articles list is empty')
    converted_times = []
    for article in articles:
        if 'published_time' not in article or 'category' not in article:
            raise ValueError('Invalid article format')
        try:
            original_datetime = article['published_time']
            target_tz = pytz.timezone(timezone)
