import numpy as np


def task_func(rows=3, columns=2):
    matrix = np.random.rand(rows, columns)
    min_val = np.min(matrix)
    max_val = np.max(matrix)
    if max_val == min_val:
        return np.zeros_like(matrix)
    scaled = (matrix - min_val) / (max_val - min_val)
    return np.clip(scaled, 0, 1)

