import json
import time
import subprocess
import platform


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError('Interval and duration must be greater than zero.')
    try:
        with open('logfile.log', 'w') as f:
            start_time = time.time()
            end_time = start_time + duration
            while time.time() < end_time:
                current_time = time.time()
                data = {'timestamp': current_time, 'cpu_usage': get_cpu_usage()
                    }
                json.dump(data, f)
                f.write('\n')
                time.sleep(interval)
    except IOError:
        return None
    return 'logfile.log'


def get_cpu_usage():
    if platform.system() == 'Windows':
        command = 'wmic CPU get LoadPercentage'
    else:
        command = "top -bn1 | grep '%Cpu'"
    try:
        output = subprocess.check_output(command, shell=True).decode()
        return parse_cpu_usage(output)
    except subprocess.CalledProcessError:
        return 0.0


def parse_cpu_usage(output):
    if platform.system() == 'Windows':
        lines = output.strip().splitlines()
        for line in reversed(lines):
            if line:
                parts = line.split(',')
                if parts:
                    val = parts[-1].strip().strip('"')
                    try:
                        return float(val)
                    except ValueError:
                        continue
        return 0.0
    else:
        lines = output.split('\n')
        for line in lines:
            if '%' in line:
                parts = line.split()
                try:
                    return float(parts[1])
                except (IndexError, ValueError):
                    continue
        return 0.0

