        if key == 'Percentage':
            return np.array(list(self.data.values()))
        raise KeyError(f'Unsupported key: {key}')


def task_func(vegetable_dict):
    """
    Compute vegetable popularity percentages with random counts.

    Parameters
    ----------
    vegetable_dict : dict
        Mapping of person names to preferred vegetables.

    Returns
    -------
    SimpleTable
        Object containing vegetable names as index and their
        percentage share as the 'Percentage' column.
    """
    if not isinstance(vegetable_dict, dict):
        raise TypeError('Input must be a dictionary')
    for person, veg in vegetable_dict.items():
        if not isinstance(person, str) or not isinstance(veg, str):
            raise ValueError('Both keys and values must be strings')
    veg_set = set(vegetable_dict.values())
    if not veg_set:
        return SimpleTable({})
    counts = {}
    for veg in veg_set:
        counts[veg] = secrets.randbelow(10) + 1
    total = sum(counts.values())
    percentages = {veg: (cnt / total * 100) for veg, cnt in counts.items()}
    logger.debug('Vegetable counts: %s', counts)
    logger.debug('Percentages: %s', percentages)
    return SimpleTable(percentages)

