import re


def task_func(request: str) ->str:
    """
    Process an HTTP GET request and return an appropriate response.

    The function extracts the filename from the request, checks if the file exists,
    and returns the content or an error message based on the file's status.
    """
    match = re.match('GET /([^ ]+) HTTP/1\\.1', request)
    if not match:
        return 'HTTP/1.1 400 BAD REQUEST\r\n\r\nBad Request'
    filename = match.group(1)
    try:
        with open(filename, 'r', encoding='utf-8') as file:
            content = file.read()
            status = (
                f'HTTP/1.1 200 OK\r\nContent-Length: {len(content)}\r\n\r\n{content}'
                )
            return status
    except FileNotFoundError:
        return 'HTTP/1.1 404 NOT FOUND\r\n\r\nFile Not Found'
    except Exception as e:
        return (
            f'HTTP/1.1 500 INTERNAL SERVER ERROR\r\n\r\nInternal Server Error')

import math


def task_func(list_of_pairs):
    """
    Calculate the product of the second values in each tuple in a list of tuples.

    Args:
        list_of_pairs (list): A list of tuples, where the first element is the category and the second element is the numeric value.

    Returns:
        numpy.ndarray: A 1D numpy array containing a single element that is the product of the second values in the list of tuples.
    """
    if not isinstance(list_of_pairs, list):
        raise TypeError('Input must be a list')
    for pair in list_of_pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError(
                'Each element in the input list must be a tuple with exactly two elements'
                )
    second_values = [pair[1] for pair in list_of_pairs]
    product = math.prod(second_values)
    return numpy.array([product])


