import re
import socket
from urllib.parse import urlparse


def task_func(myString):

    def extract_urls(s):
        return re.findall('https?://[^\\s,]+', s)

    def get_domain(url):
        parsed = urlparse(url)
        return parsed.netloc

    def get_ip(domain):
        try:
            return socket.gethostbyname(domain)
        except socket.gaierror:
            return None
    urls = extract_urls(myString)
    result = {}
    for url in urls:
        domain = get_domain(url)
        if domain:
            ip = get_ip(domain)
            result[domain] = ip
    return result

