    age_idx = rng.integers(0, len(ages), size=num_samples)
    gender_idx = rng.integers(0, len(genders), size=num_samples)
    df = pd.DataFrame({'Country': [countries[i] for i in country_idx],
        'Age': [ages[i] for i in age_idx], 'Gender': gender_idx})
    return df

