import json
import re
from collections import Counter


def task_func(json_str, *args):
    """
    Extract URLs from a JSON string and return a dictionary mapping each URL
    to the number of times it appears. If a second argument is supplied,
    it specifies the maximum number of top URLs to return.
    """
    pattern = 'https?://[^\\s]+|www\\.[^\\s]+'
    data = json.loads(json_str)
    urls = []
    stack = [data]
    while stack:
        current = stack.pop()
        for value in current.values():
            if isinstance(value, dict):
                stack.append(value)
            elif isinstance(value, str) and re.fullmatch(pattern, value):
                urls.append(value)
    if not urls:
        return {}
    counter = Counter(urls)
    top_n = args[0] if args else None
    if top_n is None or len(counter) <= top_n:
        return dict(counter)
    return dict(counter.most_common(top_n))

