            ann[k] = v.__name__
        else:
            ann[k] = str(v)
    ann_dup = {}
    for k, v in f.__annotations__.items():
        if isinstance(v, type):
            ann_dup[k] = v.__name__
        else:
            ann_dup[k] = str(v)
    lam = isinstance(f, types.LambdaType)
    res = {}
    res['function_name'] = fn
    res['args'] = ar
    res['defaults'] = de
    res['annotations'] = ann
    res['is_lambda'] = lam
    return json.dumps(res)

