import pandas as pd
import re
from collections import defaultdict
import logging
from typing import List, Dict, Any
logging.basicConfig(level=logging.INFO)


def task_func(text: str) ->pd.DataFrame:
    pattern = 'Name: (.*?), Email: (.*?), Age: (.*?), Country: (.*?)($|\\n)'
    if not isinstance(text, str):
        raise TypeError('Input must be a string')
    matches = re.findall(pattern, text)
    if not matches:
        logging.warning('No data found in the input text')
        return pd.DataFrame()
    columns = ['Name', 'Email', 'Age', 'Country']
    data_dict: Dict[str, List[Any]] = defaultdict(list)
    for match in matches:
        for i in range(len(columns)):
            if i == 2:
                try:
                    value = int(match[i])
                except ValueError:
                    value = None
            else:
                value = match[i]
            data_dict[columns[i]].append(value)
    df = pd.DataFrame(data_dict)
    if 'Age' in df.columns:
        try:
            df['Age'] = df['Age'].astype(int)
        except (ValueError, TypeError) as e:
            logging.error(f'Failed to convert Age to integer: {e}')
            pass
    return df

