import logging
import statistics


def task_func(L):
    if not isinstance(L, list):
        raise TypeError('Input must be a list')
    for sub in L:
        if not isinstance(sub, list):
            raise TypeError('All elements must be lists')
    if not isinstance(L, list):
        raise TypeError('Input must be a list')
    for sub in L:
        if not isinstance(sub, list):
            raise TypeError('All elements must be lists')
    flattened_mean = []
    for sub in L:
        for item in sub:
            flattened_mean.append(item)
    flattened_variance = []
    for sub in L:
        for item in sub:
            flattened_variance.append(item)
    try:
        mean_val = statistics.mean(flattened_mean)
    except statistics.StatisticsError:
        mean_val = float('nan')
    try:
        var_val = statistics.pvariance(flattened_variance)
    except statistics.StatisticsError:
        var_val = float('nan')
    logging.basicConfig(level=logging.INFO)
    logging.info(f'Mean: {mean_val}, Variance: {var_val}')
    return {'mean': mean_val, 'variance': var_val}

