import pandas as pd
import numpy as np
from sklearn.preprocessing import StandardScaler


def task_func(data):
    dataframe = pd.DataFrame(data)

    def is_numeric(col):
        try:
            col.astype(float)
            return True
        except ValueError:
            return False
    numeric_cols = []
    for col in dataframe.columns:
        if dataframe[col].dtype in ['float64', 'int64']:
            numeric_cols.append(col)
        elif is_numeric(dataframe[col]):
            numeric_cols.append(col)
    scaler = StandardScaler()
    for col in numeric_cols:
        try:
            scaled_values = scaler.fit_transform(dataframe[col].values.
                reshape(-1, 1))
            dataframe[col] = scaled_values.flatten()
        except Exception as e:
            pass
    return dataframe

