import geopy.distance


def task_func(data, target, k):
    if not isinstance(k, int) or k < 0:
        raise ValueError("'k' must be a non-negative integer")

    def calculate_distance(coord1, coord2):
        return geopy.distance.geodesic((coord1[0], coord1[1]), (coord2[0],
            coord2[1])).km
    distances = [calculate_distance(target, coord) for coord in data.values]
    nearest_indices = sorted(range(len(distances)), key=lambda i: distances[i]
        )[:k]
    nearest_neighbors = data.iloc[nearest_indices].values.tolist()
    return nearest_neighbors

