import matplotlib.pyplot as plt
from collections import Counter


def task_func(list_of_menuitems, title='Menu Distribution', color='blue',
    width=1.0):
    if isinstance(list_of_menuitems, str):
        raise ValueError('Input cannot be a string')
    if not isinstance(list_of_menuitems, list):
        raise TypeError('Input must be a list')
    if not list_of_menuitems:
        raise ValueError('Input list cannot be empty')
    all_items = []
    for sub in list_of_menuitems:
        if not isinstance(sub, list):
            raise TypeError('Each element must be a list')
        if sub:
            for item in sub:
                if not isinstance(item, str):
                    raise TypeError('Menu items must be strings')
                all_items.append(item)
    if not all_items:
        raise ValueError('No menu items found')
    counts = Counter(all_items)
    labels = sorted(counts)
    heights = [counts[label] for label in labels]
    fig, ax = plt.subplots()
    ax.bar(labels, heights, color=color, width=width)
    ax.set_title(title)
    ax.set_xlabel('Menu Items')
    ax.set_ylabel('Frequency')
    return ax

import pandas as pd
import numpy as np


def task_func(d):
    cols = ['x', 'y', 'z']
    if not d:
        return pd.DataFrame(columns=cols)
    result = {}
    for col in cols:
        values = [item.get(col) for item in d]
        numeric_vals = [v for v in values if v is not None]
        if not numeric_vals:
            scaled = [None] * len(values)
        else:
            vmin = min(numeric_vals)
            vmax = max(numeric_vals)
            if vmin == vmax:
                scaled = [(0.0 if v is not None else None) for v in values]
            else:
                scaled = [((v - vmin) / (vmax - vmin) if v is not None else
                    None) for v in values]
        result[col] = scaled
    return pd.DataFrame(result)

