import csv
import io


def task_func(filename, from_encoding, to_encoding, delimiter):

    def read_csv_file(file_path, encoding):
        with io.open(file_path, 'r', encoding=encoding) as f:
            return f.read()

    def convert_encoding(content, from_enc, to_enc):
        return content.encode(from_enc).decode(to_enc)

    def process_data(data, delimiter_char):
        file_like = io.StringIO(data)
        reader = csv.DictReader(file_like, delimiter=delimiter_char)
        return list(reader), reader.fieldnames if reader.fieldnames else [
            'Column']

    def write_csv_file(fieldnames, data_rows, delimiter_str):
        output = io.StringIO()
        writer = csv.DictWriter(output, fieldnames=fieldnames, delimiter=
            delimiter_str)
        writer.writeheader()
        writer.writerows(data_rows)
        return output.getvalue().replace('\r\n', '\n')
    content = read_csv_file(filename, from_encoding)
    converted_content = convert_encoding(content, from_encoding, to_encoding)
    data_list, fieldnames = process_data(converted_content, delimiter)
    converted_str = write_csv_file(fieldnames, data_list, delimiter)
    return data_list, converted_str

