import ctypes, os, shutil, glob, pathlib


def task_func(filepath, destination_dir):
    """Load a DLL and move all DLLs in its directory to destination."""
    lib = ctypes.CDLL(filepath)
    dll_dir = pathlib.Path(filepath).parent
    dll_files = {str(p) for p in glob.glob(str(dll_dir / '*.dll'))}
    move_map = {f: destination_dir for f in dll_files}
    for src, dst in move_map.items():
        shutil.move(src, dst)
    return lib._name

